<script setup lang="ts">
definePageMeta({ layout: 'auth', middleware: 'guest' }); useSeoMeta({ title: 'Create account', robots: 'noindex' })
const auth = useAuthStore(); const email = ref(''); const displayName = ref(''); const password = ref(''); const pending = ref(false); const error = ref<unknown>()
async function submit() { pending.value = true; error.value = undefined; try { await auth.register({ email: email.value, displayName: displayName.value, password: password.value }); await navigateTo('/app') } catch (caught) { error.value = caught } finally { pending.value = false } }
</script>
<template><UCard><template #header><h1>Create your workspace</h1><p>Your learning data stays under your account.</p></template><form class="form" @submit.prevent="submit"><UFormField label="Display name" required><UInput v-model="displayName" autocomplete="name" class="w-full" /></UFormField><UFormField label="Email" required><UInput v-model="email" type="email" autocomplete="email" class="w-full" /></UFormField><UFormField label="Password" required hint="Use at least 12 characters."><UInput v-model="password" type="password" autocomplete="new-password" class="w-full" /></UFormField><p v-if="error" class="form-error">{{ error instanceof Error ? error.message : 'Unable to create the account.' }}</p><UButton type="submit" block :loading="pending" label="Create account" /></form><template #footer><p>Already registered? <NuxtLink to="/login">Sign in</NuxtLink></p></template></UCard></template>
<style scoped>h1 { font-size: 1.5rem; font-weight: 700; }h1 + p { color: var(--ui-text-muted); }.form { display: grid; gap: 1rem; }.form-error { color: var(--ui-error); font-size: .85rem; }a { color: var(--ui-primary); font-weight: 600; }</style>
